// ---- src/normalize.js ----
// Validates and normalizes intake requests. Contract: docs/v2/event-contract.md.
// No I/O; the current time is passed in so tests stay deterministic. Every
// rejected event is reported with its index and reasons; nothing invalid
// reaches the database.

const MAX_EVENTS_PER_REQUEST = 50;
const MAX_EVENT_BYTES = 20000;
// occurred_at may be at most this far ahead of our clock (sender clock skew).
// Further ahead would freeze the contact: later events would count as older.
// lq_v2.accept_event enforces the same limit.
const MAX_FUTURE_SKEW_MS = 5 * 60 * 1000;
const EVENT_ID_RE = /^[A-Za-z0-9._:-]{1,200}$/;
const SOURCE_RE = /^[a-z0-9_-]{1,40}$/;
const EMAIL_RE = /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[^\s@<>()",;]+$/;

// field -> [accepted input names (first match wins), max length]
const TEXT_FIELDS = {
  first_name: [['first_name', 'firstName'], 100],
  last_name: [['last_name', 'lastName'], 100],
  phone: [['phone'], 50],
  company: [['company'], 200],
  website: [['website'], 255],
  industry: [['industry'], 100],
  job_title: [['job_title', 'jobTitle'], 200],
  lead_source: [['lead_source', 'leadSource'], 100],
  first_conversion: [['first_conversion', 'firstConversion'], 200],
  recent_conversion: [['recent_conversion', 'recentConversion'], 200],
  message: [['message'], 5000]
};

function pick(obj, names) {
  for (const n of names) {
    if (obj[n] !== undefined && obj[n] !== null) return { name: n, value: obj[n] };
  }
  return { name: names[0], value: null };
}

function readText(ev, names, maxLen, errors) {
  const { name, value } = pick(ev, names);
  if (value === null) return null;
  if (typeof value !== 'string') {
    errors.push({ field: name, problem: 'must be a string' });
    return null;
  }
  const v = value.trim();
  if (v.length > maxLen) {
    errors.push({ field: name, problem: `must be at most ${maxLen} characters` });
    return null;
  }
  return v === '' ? null : v;
}

function readNumber(ev, names, { integer }, errors) {
  const { name, value } = pick(ev, names);
  if (value === null || value === '') return null;
  let n;
  if (typeof value === 'number') n = value;
  else if (typeof value === 'string' && /^\s*\d+(\.\d+)?\s*$/.test(value)) n = Number(value);
  else {
    errors.push({ field: name, problem: 'must be a non-negative number' });
    return null;
  }
  if (!Number.isFinite(n) || n < 0 || n > 1e12) {
    errors.push({ field: name, problem: 'must be a non-negative number' });
    return null;
  }
  if (integer && !Number.isInteger(n)) {
    errors.push({ field: name, problem: 'must be a whole number' });
    return null;
  }
  return n;
}

function normalizeEvent(ev, nowMs = Date.now()) {
  const errors = [];
  if (ev === null || typeof ev !== 'object' || Array.isArray(ev)) {
    return { errors: [{ field: '(event)', problem: 'must be a JSON object' }] };
  }
  if (JSON.stringify(ev).length > MAX_EVENT_BYTES) {
    return { errors: [{ field: '(event)', problem: `must be at most ${MAX_EVENT_BYTES} bytes` }] };
  }

  let sourceEventId = null;
  if (typeof ev.source_event_id !== 'string' || !EVENT_ID_RE.test(ev.source_event_id)) {
    errors.push({ field: 'source_event_id', problem: 'required; 1-200 chars of A-Z a-z 0-9 . _ : -' });
  } else {
    sourceEventId = ev.source_event_id;
  }

  let source = 'synthetic';
  if (ev.source !== undefined && ev.source !== null) {
    if (typeof ev.source !== 'string' || !SOURCE_RE.test(ev.source)) {
      errors.push({ field: 'source', problem: '1-40 chars of a-z 0-9 _ -' });
    } else {
      source = ev.source;
    }
  }

  let occurredAt = null;
  if (ev.occurred_at !== undefined && ev.occurred_at !== null) {
    const t = typeof ev.occurred_at === 'string' ? Date.parse(ev.occurred_at) : NaN;
    if (Number.isNaN(t)) errors.push({ field: 'occurred_at', problem: 'must be an ISO 8601 timestamp' });
    else if (t > nowMs + MAX_FUTURE_SKEW_MS) errors.push({ field: 'occurred_at', problem: 'must not be more than 5 minutes in the future' });
    else occurredAt = new Date(t).toISOString();
  }

  let email = null;
  if (typeof ev.email !== 'string') {
    errors.push({ field: 'email', problem: 'required string' });
  } else {
    const e = ev.email.trim().toLowerCase();
    if (e.length === 0 || e.length > 254 || !EMAIL_RE.test(e)) {
      errors.push({ field: 'email', problem: 'must be a valid email address' });
    } else {
      email = e;
    }
  }

  let crmObjectId = null;
  if (ev.crm_object_id !== undefined && ev.crm_object_id !== null) {
    const v = ev.crm_object_id;
    if ((typeof v === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(v)) || (Number.isInteger(v) && v >= 0)) {
      crmObjectId = String(v);
    } else {
      errors.push({ field: 'crm_object_id', problem: 'string or integer id, max 64 chars' });
    }
  }

  const text = {};
  for (const [field, [names, maxLen]] of Object.entries(TEXT_FIELDS)) {
    text[field] = readText(ev, names, maxLen, errors);
  }
  const employeeCount = readNumber(ev, ['employee_count', 'employeeCount'], { integer: true }, errors);
  const dealSize = readNumber(ev, ['deal_size', 'dealSize'], { integer: false }, errors);

  if (errors.length) return { source_event_id: sourceEventId, errors };

  const name = [text.first_name, text.last_name].filter(Boolean).join(' ') || null;
  return {
    event: {
      source,
      source_event_id: sourceEventId,
      occurred_at: occurredAt,
      contact: {
        email,
        crm_object_id: crmObjectId,
        name,
        phone: text.phone,
        company: text.company,
        website: text.website,
        industry: text.industry,
        job_title: text.job_title,
        employee_count: employeeCount,
        deal_size: dealSize
      },
      // Exactly what the scorer sees; persisted with the score.
      scoring_input: {
        employee_count: employeeCount,
        job_title: text.job_title,
        deal_size: dealSize,
        lead_source: text.lead_source || 'unknown',
        first_conversion: text.first_conversion,
        recent_conversion: text.recent_conversion
      },
      message: text.message,
      raw: ev
    }
  };
}

// body: one event object, or an array of 1..MAX_EVENTS_PER_REQUEST events.
// nowMs: current time in epoch ms (defaults to the system clock).
function normalizeRequest(body, nowMs = Date.now()) {
  let list;
  if (Array.isArray(body)) {
    if (body.length === 0 || body.length > MAX_EVENTS_PER_REQUEST) {
      return {
        valid: [],
        invalid: [{ index: null, source_event_id: null, errors: [{ field: '(body)', problem: `array must hold 1-${MAX_EVENTS_PER_REQUEST} events` }] }]
      };
    }
    list = body;
  } else if (body !== null && typeof body === 'object') {
    list = [body];
  } else {
    return {
      valid: [],
      invalid: [{ index: null, source_event_id: null, errors: [{ field: '(body)', problem: 'must be a JSON object or array' }] }]
    };
  }

  const valid = [];
  const invalid = [];
  list.forEach((ev, index) => {
    const r = normalizeEvent(ev, nowMs);
    if (r.errors) {
      invalid.push({ index, source_event_id: r.source_event_id || null, errors: r.errors });
      return;
    }
    r.event.index = index;
    valid.push(r.event);
  });
  return { valid, invalid };
}

// ---- src/score.js ----
// Deterministic lead scoring, ported unchanged from the v1 "Calculate Scores" node
// (lead-qualification-production-v1.json). Weights, regexes, thresholds and the
// reason text are identical; test/unit/score-parity.test.js runs the original
// node code against the same fixtures to prove it.
//
// Only addition: `missing_inputs` in the breakdown, so a missing deal size is
// explicit instead of silently scoring 0.

const SCORE_VERSION = 'rule-based-v1';
const FIT_CALL_NOW = 80;
const FIT_NURTURE = 50;

function routeForFit(fit) {
  if (fit >= FIT_CALL_NOW) return 'call_now';
  if (fit >= FIT_NURTURE) return 'nurture';
  return 'manual_review';
}

function scoreLead(s) {
  s = s || {};

  // ============ FIT SCORE (0-100) ============
  let companySizeScore = 0;
  const employees = parseInt(s.employee_count) || 0;
  if (employees >= 1000) companySizeScore = 30;
  else if (employees >= 500) companySizeScore = 25;
  else if (employees >= 100) companySizeScore = 20;
  else if (employees >= 50) companySizeScore = 15;
  else if (employees >= 10) companySizeScore = 8;
  else if (employees > 0) companySizeScore = 3;
  else companySizeScore = 0;

  let titleScore = 0;
  const title = (s.job_title || '').toLowerCase();
  if (title.match(/^(ceo|cto|cfo|cmo|coo|chief|founder|owner|president)/)) titleScore = 40;
  else if (title.match(/(vp|vice president|director)/)) titleScore = 32;
  else if (title.match(/(head of|senior manager|sr\. manager)/)) titleScore = 25;
  else if (title.match(/manager/)) titleScore = 18;
  else if (title.match(/(lead|principal|senior)/)) titleScore = 12;
  else if (title.match(/(engineer|developer|analyst|specialist)/)) titleScore = 6;
  else titleScore = 0;

  let dealScore = 0;
  const dealSize = parseFloat(s.deal_size) || 0;
  if (dealSize >= 100000) dealScore = 30;
  else if (dealSize >= 50000) dealScore = 24;
  else if (dealSize >= 25000) dealScore = 18;
  else if (dealSize >= 10000) dealScore = 12;
  else if (dealSize > 0) dealScore = 6;
  else dealScore = 0;

  const fitScore = Math.min(100, companySizeScore + titleScore + dealScore);

  // ============ URGENCY SCORE (0-100) ============
  let sourceScore = 0;
  const source = (s.lead_source || '').toLowerCase();
  if (source.match(/referral|partner/)) sourceScore = 40;
  else if (source.match(/demo|request|pricing/)) sourceScore = 38;
  else if (source.match(/organic|search/)) sourceScore = 28;
  else if (source.match(/paid|ads|ppc/)) sourceScore = 22;
  else if (source.match(/social|linkedin|twitter/)) sourceScore = 18;
  else if (source.match(/email|campaign/)) sourceScore = 14;
  else sourceScore = 8;

  let conversionScore = 0;
  const firstConv = (s.first_conversion || '').toLowerCase();
  const recentConv = (s.recent_conversion || '').toLowerCase();
  if (firstConv.match(/demo|pricing|contact sales/)) conversionScore += 20;
  else if (firstConv.match(/trial|signup/)) conversionScore += 15;
  else if (firstConv.match(/whitepaper|ebook|webinar/)) conversionScore += 8;
  if (recentConv.match(/demo|pricing|contact sales/)) conversionScore += 15;
  else if (recentConv.match(/trial|signup/)) conversionScore += 10;
  conversionScore = Math.min(35, conversionScore);

  // v1 behavior preserved: timing always contributes 25.
  const timingScore = 25;

  const urgencyScore = Math.min(100, sourceScore + conversionScore + timingScore);

  const reason = [
    `FIT (${fitScore}/100): Company size ${companySizeScore}/30, Title ${titleScore}/40, Deal potential ${dealScore}/30.`,
    `URGENCY (${urgencyScore}/100): Source quality ${sourceScore}/40, Conversion signals ${conversionScore}/35, Timing ${timingScore}/25.`,
    `Recommendation: ${fitScore >= 80 ? 'HIGH PRIORITY - Call immediately' : fitScore >= 50 ? 'MEDIUM - Add to nurture sequence' : 'LOW - Manual review needed'}`
  ].join(' ');

  const missingInputs = ['employee_count', 'job_title', 'deal_size'].filter(
    (k) => s[k] === null || s[k] === undefined || s[k] === ''
  );

  return {
    fit: fitScore,
    urgency: urgencyScore,
    route: routeForFit(fitScore),
    reason: reason,
    score_version: SCORE_VERSION,
    breakdown: {
      fit: { company_size: companySizeScore, title: titleScore, deal_size: dealScore },
      urgency: { source: sourceScore, conversion: conversionScore, timing: timingScore },
      missing_inputs: missingInputs
    }
  };
}

// ---- src/notify.js ----
// Slack notification helpers: message rendering, send-result classification and
// reconciliation lookup. Pure functions; the n8n dispatcher does the HTTP calls.
// State machine: docs/v2/delivery-contract.md.

const METADATA_EVENT_TYPE = 'lq_v2_notification';

// Slack mrkdwn control characters. Escaping stops lead-supplied text from
// injecting mentions such as <!channel> or links.
function slackEscape(v) {
  return String(v === null || v === undefined ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function correlationIdFor(event) {
  return `lqv2:${event.source}:${event.source_event_id}`;
}

// Content preserved from the v1 "Send Slack Alert" node. The localhost
// workflow link is replaced by the correlation reference.
function renderSlackText(event, score) {
  const c = event.contact;
  return [
    '🔥 *HIGH PRIORITY LEAD - CALL NOW*',
    '',
    `*Name:* ${slackEscape(c.name)}`,
    `*Company:* ${slackEscape(c.company)}`,
    `*Email:* ${slackEscape(c.email)}`,
    '',
    `*Fit Score:* ${score.fit}/100`,
    `*Urgency Score:* ${score.urgency}/100`,
    '',
    `*Analysis:* ${slackEscape(score.reason)}`,
    '',
    `*Ref:* ${slackEscape(correlationIdFor(event))}`
  ].join('\n');
}

const RETRYABLE_SLACK_ERRORS = new Set(['ratelimited', 'rate_limited', 'service_unavailable']);
const AMBIGUOUS_SLACK_ERRORS = new Set(['internal_error', 'fatal_error', 'request_timeout']);
// Network errors where the request cannot have reached Slack. Includes n8n's
// humanized wording for a refused connection. Everything else (n8n reports
// timeouts as "The connection was aborted...") stays uncertain.
const NOT_DELIVERED_NETWORK_RE = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ENETUNREACH|EHOSTUNREACH|CERT_|certificate|refused the connection/i;

function parseBody(body) {
  if (typeof body === 'string') {
    try {
      return JSON.parse(body);
    } catch (e) {
      return null;
    }
  }
  return body && typeof body === 'object' ? body : null;
}

// Input: { statusCode, body } for an HTTP response, or { error } when no
// response arrived. Output outcome is one of:
//   sent | retryable_failure | permanent_failure | uncertain
// Anything we cannot prove either way is "uncertain", never "failed".
function classifySendResponse({ statusCode, body, error }) {
  if (error !== undefined && error !== null && statusCode === undefined) {
    const text = typeof error === 'string' ? error : JSON.stringify(error);
    if (NOT_DELIVERED_NETWORK_RE.test(text)) {
      return { outcome: 'retryable_failure', provider_error: 'network: ' + text.slice(0, 300) };
    }
    return { outcome: 'uncertain', provider_error: 'no response: ' + text.slice(0, 300) };
  }

  const b = parseBody(body);
  if (statusCode === 429) return { outcome: 'retryable_failure', provider_error: 'ratelimited', http_status: 429 };
  if (statusCode >= 500) return { outcome: 'uncertain', provider_error: `http_${statusCode}`, http_status: statusCode };
  if (statusCode >= 400) {
    return { outcome: 'permanent_failure', provider_error: (b && b.error) || `http_${statusCode}`, http_status: statusCode };
  }
  if (!b) return { outcome: 'uncertain', provider_error: 'unparseable_response', http_status: statusCode };

  if (b.ok === true) {
    if (typeof b.ts === 'string' && b.ts && typeof b.channel === 'string' && b.channel) {
      return { outcome: 'sent', message_ts: b.ts, provider_channel: b.channel, http_status: statusCode };
    }
    // Slack says ok but gave no receipt: it probably posted. Reconcile.
    return { outcome: 'uncertain', provider_error: 'ok_without_receipt', http_status: statusCode };
  }
  const err = typeof b.error === 'string' ? b.error : 'unknown_error';
  if (RETRYABLE_SLACK_ERRORS.has(err)) return { outcome: 'retryable_failure', provider_error: err, http_status: statusCode };
  if (AMBIGUOUS_SLACK_ERRORS.has(err)) return { outcome: 'uncertain', provider_error: err, http_status: statusCode };
  return { outcome: 'permanent_failure', provider_error: err, http_status: statusCode };
}

// Looks for our message in a conversations.history response.
// found: message exists (with ts). not_found: conclusive absence.
// reconcile_error: could not decide (API error or more pages to read).
function findReconciledMessage({ statusCode, body, error }, notificationId) {
  if (error !== undefined && error !== null && statusCode === undefined) {
    return { outcome: 'reconcile_error', provider_error: 'no response: ' + String(typeof error === 'string' ? error : JSON.stringify(error)).slice(0, 300) };
  }
  const b = parseBody(body);
  if (!b || b.ok !== true || !Array.isArray(b.messages)) {
    return { outcome: 'reconcile_error', provider_error: (b && b.error) || `http_${statusCode}`, http_status: statusCode };
  }
  const hit = b.messages.find(
    (m) =>
      m &&
      m.metadata &&
      m.metadata.event_type === METADATA_EVENT_TYPE &&
      m.metadata.event_payload &&
      m.metadata.event_payload.notification_id === notificationId
  );
  if (hit) return { outcome: 'found', message_ts: hit.ts, http_status: statusCode };
  if (b.has_more) return { outcome: 'reconcile_error', provider_error: 'inconclusive_more_pages', http_status: statusCode };
  return { outcome: 'not_found', http_status: statusCode };
}

// ---- src/intake.js ----
// Intake preparation: validate, score and render each event, producing the
// payloads sent to public.lq_v2_accept_batch. This is the full logic of the
// "Validate and Score" Code node; the build inlines it.


function prepareIntake(body, config) {
  const { valid, invalid } = normalizeRequest(body, config.nowMs);
  const events = valid.map((e) => {
    const score = scoreLead(e.scoring_input);
    return {
      ...e,
      score,
      notification: { target: config.slackChannelId, text: renderSlackText(e, score) }
    };
  });
  return { events, invalid };
}

// ---- node ----
const SLACK_CHANNEL_ID = "__LQ_V2_SLACK_CHANNEL_ID__";
const body = $input.first().json.body;
const { events, invalid } = prepareIntake(body, { slackChannelId: SLACK_CHANNEL_ID });
return [{ json: { events, invalid } }];

// ---- src/response.js ----
// Builds the intake HTTP response from validation rejects and database results.
// Status rules (docs/v2/event-contract.md):
//   202 every event accepted or duplicate
//   400 nothing accepted, all invalid/rejected
//   409 nothing accepted, all conflicts (event id reused with different payload)
//   207 mixed
//   503 database did not confirm acceptance (built separately in the workflow)

function buildIntakeResponse(invalid, dbResults) {
  const results = [
    ...invalid.map((r) => ({ index: r.index, source_event_id: r.source_event_id, outcome: 'invalid', errors: r.errors })),
    ...(dbResults || [])
  ].sort((a, b) => (a.index === null ? -1 : b.index === null ? 1 : a.index - b.index));

  const ok = results.filter((r) => r.outcome === 'accepted' || r.outcome === 'duplicate').length;
  const bad = results.length - ok;
  let statusCode;
  if (bad === 0) statusCode = 202;
  else if (ok > 0) statusCode = 207;
  else if (results.every((r) => r.outcome === 'conflict')) statusCode = 409;
  else statusCode = 400;

  return { statusCode, body: { status: statusCode, results } };
}

// ---- node ----
const prep = $('Validate and Score').first().json;
const db = $input.first().json;
// From the "no valid events" branch the input is the prep item itself.
if (db.statusCode === undefined) return [{ json: buildIntakeResponse(prep.invalid, []) }];
let body = db.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
if (db.statusCode >= 200 && db.statusCode < 300 && body && Array.isArray(body.results)) {
  return [{ json: buildIntakeResponse(prep.invalid, body.results) }];
}
// The database did not confirm acceptance. Nothing was committed, so the
// sender must retry; retries are safe because acceptance is idempotent.
// A misconfiguration (e.g. malformed Slack channel) lands here too, so
// `alert` makes "Raise Intake Alert" page ops after the 503 is sent.
const detail = body && body.message ? body.message : (typeof db.body === 'string' ? db.body : JSON.stringify(db.body));
const alert = `LQ v2 intake could not confirm acceptance (database HTTP ${db.statusCode}): ${String(detail).slice(0, 300)}`;
return [{ json: { statusCode: 503, body: { status: 503, error: 'not_accepted', retry: true }, alert } }];

const alert = $input.first().json.alert;
if (alert) throw new Error(alert);
return $input.all();
